//! Rings, provinces, wedges and Marches (design §3.1).
//!
//! * **Tiles** are the axial hexes of `crate::hex`, bounded to
//!   |q|, |r| ≤ 2¹⁶ at every entry point ([`check_hex`], WP08).
//! * **Provinces** are radius-4 hexagons of 61 tiles. They tile the plane on
//!   the lattice generated by A = (9, −4) and its 60° turn B = (4, 5):
//!   province (P, Q) is centred at `P·A + Q·B`. Turning the world by 60°
//!   maps B to B − A, so (P, Q) are themselves axial coordinates of a hex
//!   grid of provinces: a province's ring is its hex distance from the
//!   Concord, and its wedge is its sextant. Any tile's province is O(1)
//!   ([`province_of`]).
//! * **Rings:** ring 0 is the Concord, ring 1 the Six Seats, ring d ≥ 2
//!   holds 6d provinces.
//! * **Wedges:** faction k's homeland is sextant k of the province grid.
//! * **Marches** group 7 provinces (a province and its six neighbours) on
//!   the radius-1 lattice of the province grid, the same construction one
//!   level up.
//!
//! Everything turns with the map: `province_of(h.rotate()) ==
//! province_of(h).rotate()`, which is what makes symmetric terrain possible
//! (`terrain`).

use crate::hash::sha256;
use crate::hex::{Hex, DIRECTIONS};
use alloc::vec::Vec;
use borsh::{BorshDeserialize, BorshSerialize};

/// Largest |q| and |r| of a tile accepted at any entry point (WP08).
pub const COORD_BOUND: i32 = 1 << 16;
/// Radius of a province in tiles.
pub const PROVINCE_RADIUS: i32 = 4;
/// Tiles per province: `3·4·5 + 1`.
pub const PROVINCE_TILES: usize = 61;
/// Settlement sites per province (design §3.1).
pub const SITES_PER_PROVINCE: usize = 12;
/// Default outermost ring of a season (`R_MAX`, owner decision D12).
pub const R_MAX_DEFAULT: u16 = 64;
/// Program hard maximum of `R_MAX` (design §3.4).
pub const R_MAX_HARD: u16 = 128;
/// Provinces in a March.
pub const MARCH_PROVINCES: usize = 7;
/// Regions for beacon anchors and seed caches (design §8.4).
pub const REGIONS: u8 = 16;
/// Player factions.
pub const FACTIONS: u8 = 6;

/// A tile coordinate outside the accepted bound.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OutOfBounds;

/// Whether `h` lies inside the accepted coordinate box.
pub const fn in_bounds(h: Hex) -> bool {
    h.q >= -COORD_BOUND && h.q <= COORD_BOUND && h.r >= -COORD_BOUND && h.r <= COORD_BOUND
}

/// `h` if it lies inside the accepted coordinate box (WP08
/// `hex-coord-i32-overflow`): every sum and product of such coordinates the
/// Frontier computes fits in `i32`.
pub const fn check_hex(h: Hex) -> Result<Hex, OutOfBounds> {
    if in_bounds(h) {
        Ok(h)
    } else {
        Err(OutOfBounds)
    }
}

/// The lattice cell of `h` for hexagons of radius `n`: the (P, Q) with
/// `|h − (P·(2n+1, −n) + Q·(n, n+1))| ≤ n`. Radius-n hexagons centred on
/// that lattice tile the plane, so the cell is unique.
pub fn cell_of(h: Hex, n: i32) -> Hex {
    let (q, r, n) = (h.q as i64, h.r as i64, n as i64);
    let det = 3 * n * n + 3 * n + 1;
    // Real coordinates of `h` in the lattice basis, floored; the cell is
    // one of the 3 × 3 lattice points around them.
    let p0 = ((n + 1) * q - n * r).div_euclid(det);
    let q0 = (n * q + (2 * n + 1) * r).div_euclid(det);
    let mut best = (u64::MAX, Hex::ORIGIN);
    for dp in -1..=1 {
        for dq in -1..=1 {
            let (pp, qq) = (p0 + dp, q0 + dq);
            let cq = (2 * n + 1) * pp + n * qq;
            let cr = -n * pp + (n + 1) * qq;
            let (a, b) = (q - cq, r - cr);
            let d = (a.unsigned_abs() + b.unsigned_abs() + (a + b).unsigned_abs()) / 2;
            if d < best.0 {
                best = (d, Hex::new(pp as i32, qq as i32));
            }
        }
    }
    best.1
}

/// Centre of lattice cell `c` for hexagons of radius `n`.
pub const fn cell_centre(c: Hex, n: i32) -> Hex {
    Hex::new((2 * n + 1) * c.q + n * c.r, -n * c.q + (n + 1) * c.r)
}

/// A province's coordinates (P, Q) on the province lattice.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, BorshSerialize, BorshDeserialize,
)]
pub struct ProvinceCoord {
    pub p: i32,
    pub q: i32,
}

impl ProvinceCoord {
    /// The Concord, ring 0.
    pub const CONCORD: ProvinceCoord = ProvinceCoord { p: 0, q: 0 };

    pub const fn new(p: i32, q: i32) -> Self {
        ProvinceCoord { p, q }
    }

    /// The province grid position as a hex (for grid arithmetic).
    pub const fn as_hex(self) -> Hex {
        Hex::new(self.p, self.q)
    }

    pub const fn from_hex(h: Hex) -> Self {
        ProvinceCoord { p: h.q, q: h.r }
    }

    /// Ring: province-grid distance from the Concord.
    pub fn ring(self) -> u32 {
        self.as_hex().radius()
    }

    /// Wedge (= homeland faction) of a province outside the Concord.
    pub fn wedge(self) -> Option<u8> {
        if self == Self::CONCORD {
            None
        } else {
            Some(self.as_hex().sextant())
        }
    }

    pub fn is_concord(self) -> bool {
        self == Self::CONCORD
    }

    /// A Seat (ring 1): a faction capital, never capturable.
    pub fn is_seat(self) -> bool {
        self.ring() == 1
    }

    /// Centre tile.
    pub const fn centre(self) -> Hex {
        cell_centre(self.as_hex(), PROVINCE_RADIUS)
    }

    /// Province-grid distance.
    pub fn distance(self, other: ProvinceCoord) -> u32 {
        self.as_hex().distance(other.as_hex())
    }

    /// The six neighbouring provinces, in `hex::DIRECTIONS` order.
    pub fn neighbors(self) -> [ProvinceCoord; 6] {
        self.as_hex().neighbors().map(Self::from_hex)
    }

    /// Turned by 60° about the Concord (the world's rotation).
    pub const fn rotate(self) -> Self {
        Self::from_hex(self.as_hex().rotate())
    }

    /// Turned by `k` × 60°.
    pub fn rotate_by(self, k: u8) -> Self {
        Self::from_hex(self.as_hex().rotate_by(k))
    }

    /// Seen from wedge `k` (turned back by `k` × 60°): the canonical copy
    /// in wedge 0 of a province in wedge `k`.
    pub fn turned(self, k: u8) -> Self {
        Self::from_hex(self.as_hex().turned(k))
    }

    /// Global hex of tile `idx` (0..61, `hexes_within(4)` order).
    pub fn tile(self, idx: u8) -> Option<Hex> {
        let o = tile_offset(idx)?;
        let c = self.centre();
        Some(Hex::new(c.q + o.q, c.r + o.r))
    }

    /// Dense index: rings in order, and inside ring d ≥ 1 wedge by wedge,
    /// `k·d + (position in the wedge)`. The Concord is 0; ring d starts at
    /// `1 + 3d(d − 1)`.
    pub fn index(self) -> u32 {
        let d = self.ring();
        if d == 0 {
            return 0;
        }
        let k = self.as_hex().sextant();
        let w = self.as_hex().turned(k); // q > 0, r ≥ 0, q + r = d
        provinces_within(d - 1) + k as u32 * d + w.r as u32
    }

    /// Inverse of [`ProvinceCoord::index`].
    pub fn from_index(i: u32) -> Self {
        if i == 0 {
            return Self::CONCORD;
        }
        // smallest d with 1 + 3d(d + 1) > i
        let mut d = (crate::fixed::isqrt(i as u64 / 3) as u32).max(1);
        while d > 1 && provinces_within(d - 1) > i {
            d -= 1;
        }
        while provinces_within(d) <= i {
            d += 1;
        }
        let pos = i - provinces_within(d - 1);
        let (k, r) = ((pos / d) as u8, (pos % d) as i32);
        let w = Hex::new(d as i32 - r, r);
        Self::from_hex(w.rotate_by(k))
    }
}

/// Provinces in ring `d`.
pub const fn ring_size(d: u32) -> u32 {
    if d == 0 {
        1
    } else {
        6 * d
    }
}

/// Provinces in rings `0..=d`: `1 + 3d(d + 1)`.
pub const fn provinces_within(d: u32) -> u32 {
    1 + 3 * d * (d + 1)
}

/// The provinces of ring `d`, in index order.
pub fn ring_provinces(d: u32) -> Vec<ProvinceCoord> {
    let first = if d == 0 { 0 } else { provinces_within(d - 1) };
    (first..first + ring_size(d))
        .map(ProvinceCoord::from_index)
        .collect()
}

/// The province of a tile, O(1).
pub fn province_of(h: Hex) -> ProvinceCoord {
    ProvinceCoord::from_hex(cell_of(h, PROVINCE_RADIUS))
}

/// The province of a tile and the tile's index in it.
pub fn locate(h: Hex) -> (ProvinceCoord, u8) {
    let p = province_of(h);
    let c = p.centre();
    let idx = tile_index(Hex::new(h.q - c.q, h.r - c.r)).unwrap_or(0);
    (p, idx)
}

/// Offset from the province centre of tile `idx`, in `hexes_within(4)`
/// order (sorted by q, then r).
pub fn tile_offset(idx: u8) -> Option<Hex> {
    const R: i32 = PROVINCE_RADIUS;
    let mut i = idx as i32;
    for q in -R..=R {
        let r_min = (-R).max(-q - R);
        let r_max = R.min(-q + R);
        let n = r_max - r_min + 1;
        if i < n {
            return Some(Hex::new(q, r_min + i));
        }
        i -= n;
    }
    None
}

/// Tile index of an offset from the province centre.
pub fn tile_index(o: Hex) -> Option<u8> {
    const R: i32 = PROVINCE_RADIUS;
    if o.radius() > R as u32 {
        return None;
    }
    let mut base = 0;
    for q in -R..o.q {
        base += R.min(-q + R) - (-R).max(-q - R) + 1;
    }
    Some((base + o.r - (-R).max(-o.q - R)) as u8)
}

/// Tile index `idx` of a province seen from wedge `k`: the index of the
/// same tile in the canonical copy (both offsets turned together).
pub fn tile_turned(idx: u8, k: u8) -> u8 {
    tile_offset(idx)
        .and_then(|o| tile_index(o.turned(k)))
        .unwrap_or(idx)
}

/// A March's coordinates on the radius-1 lattice of the province grid.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, BorshSerialize, BorshDeserialize,
)]
pub struct MarchCoord {
    pub m: i32,
    pub n: i32,
}

/// The March a province belongs to.
pub fn march_of(p: ProvinceCoord) -> MarchCoord {
    let c = cell_of(p.as_hex(), 1);
    MarchCoord { m: c.q, n: c.r }
}

/// The 7 provinces of a March: its centre, then the neighbours in
/// `hex::DIRECTIONS` order.
pub fn march_members(m: MarchCoord) -> [ProvinceCoord; MARCH_PROVINCES] {
    let c = cell_centre(Hex::new(m.m, m.n), 1);
    let mut out = [ProvinceCoord::from_hex(c); MARCH_PROVINCES];
    for (j, (dq, dr)) in DIRECTIONS.iter().enumerate() {
        out[j + 1] = ProvinceCoord::from_hex(Hex::new(c.q + dq, c.r + dr));
    }
    out
}

/// The Seat (ring-1 capital) of `faction`.
pub fn seat_of(faction: u8) -> ProvinceCoord {
    ProvinceCoord::new(1, 0).rotate_by(faction % 6)
}

/// Heartland: rings 2–3 of a faction's own wedge (design §3.1). No sieges
/// there without War (or March hostility).
pub fn is_heartland(p: ProvinceCoord, faction: u8) -> bool {
    matches!(p.ring(), 2 | 3) && p.wedge() == Some(faction)
}

/// Region of a province for beacon anchors and seed caches:
/// `sha256("frontier/region" ‖ P ‖ Q)[0] mod 16` (design §8.4).
pub fn region_of(p: ProvinceCoord) -> u8 {
    sha256(&[b"frontier/region", &p.p.to_le_bytes(), &p.q.to_le_bytes()])[0] % REGIONS
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hex::hexes_within;

    #[test]
    fn tile_index_round_trips() {
        let offs = hexes_within(PROVINCE_RADIUS as u32);
        assert_eq!(offs.len(), PROVINCE_TILES);
        for (i, o) in offs.iter().enumerate() {
            assert_eq!(tile_offset(i as u8), Some(*o));
            assert_eq!(tile_index(*o), Some(i as u8));
        }
        assert_eq!(tile_offset(61), None);
        assert_eq!(tile_index(Hex::new(5, 0)), None);
    }

    #[test]
    fn index_round_trips_and_counts() {
        for i in 0..provinces_within(20) {
            let p = ProvinceCoord::from_index(i);
            assert_eq!(p.index(), i, "{p:?}");
        }
        for d in 0..12 {
            let ring = ring_provinces(d);
            assert_eq!(ring.len() as u32, ring_size(d));
            assert!(ring.iter().all(|p| p.ring() == d));
        }
    }
}
